//! Icon names are [Phosphor](https://phosphoricons.com) names (data/phosphor-icons.tsv, generated by
//! tools/gen-icon-catalog.mjs). The compiler keeps every emitted icon valid: exact names pass, common lucide-style names
//! map to their Phosphor equivalent, near misses are corrected, and anything else (or no icon at all for an app) is
//! picked by keywords from the catalog's tags.

use std::collections::HashMap;
use std::sync::LazyLock;

use crate::util::levenshtein;

const TSV: &str = include_str!("../data/phosphor-icons.tsv");

/// The generic app icon when nothing matches.
pub const FALLBACK: &str = "app-window";

struct Entry {
    name: &'static str,
    /// Hyphen-separated parts of the name (`chart-line-up` → chart, line, up).
    parts: Vec<&'static str>,
    /// Stemmed words of the tags and categories.
    words: Vec<String>,
}

static CATALOG: LazyLock<Vec<Entry>> = LazyLock::new(|| {
    TSV.lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .filter_map(|line| {
            let mut cols = line.split('\t');
            let name = cols.next()?;
            let mut words = Vec::new();
            for col in cols {
                for tag in col.split(',').filter(|t| !t.starts_with('*')) {
                    words.extend(tag.split([' ', '&', '-']).filter(|w| w.len() >= 3).map(stem));
                }
            }
            Some(Entry { name, parts: name.split('-').collect(), words })
        })
        .collect()
});

static BY_NAME: LazyLock<HashMap<&'static str, usize>> =
    LazyLock::new(|| CATALOG.iter().enumerate().map(|(i, e)| (e.name, i)).collect());

