/// How a requested icon was resolved.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Resolution {
    Exact,
    Alias,
    Fuzzy,
    Keywords,
    Fallback,
}

/// Resolves an `icon` value written in a spec: exact names pass silently, anything else is mapped with a warning.
pub fn resolve_prop(requested: &str, context: &str, path: &str, diags: &mut crate::diag::Diags) -> &'static str {
    let (name, how) = resolve(Some(requested), context);
    if how != Resolution::Exact {
        diags
            .warn("W_ICON", path, format!("`{requested}` isn't a Phosphor icon; using `{name}`"))
            .hint("Icons are Phosphor names, e.g. barbell, drop, wallet, coffee, book-open, check-circle, trash");
    }
    name
}

pub fn is_icon(name: &str) -> bool {
    BY_NAME.contains_key(name)
}

/// Resolves a requested icon (if any) to a Phosphor name. `context` (app name, description, archetype) guides the
/// keyword pick when the request is missing or unknown.
pub fn resolve(requested: Option<&str>, context: &str) -> (&'static str, Resolution) {
    if let Some(raw) = requested {
        let wanted = raw.trim().to_ascii_lowercase().replace(['_', ' '], "-");
        if let Some(&i) = BY_NAME.get(wanted.as_str()) {
            return (CATALOG[i].name, Resolution::Exact);
        }
        if let Some((_, to)) = ALIASES.iter().find(|(from, _)| *from == wanted) {
            return (to, Resolution::Alias);
        }
        let base = wanted.trim_end_matches(|c: char| c.is_ascii_digit() || c == '-');
        if let Some(&i) = BY_NAME.get(base) {
            return (CATALOG[i].name, Resolution::Fuzzy);
        }
        if wanted.len() >= 5
            && let Some(e) = CATALOG
                .iter()
                .map(|e| (levenshtein(&wanted, e.name), e))
                .filter(|(d, _)| *d <= 2)
                .min_by_key(|(d, e)| (*d, e.name.len()))
                .map(|(_, e)| e)
        {
            return (e.name, Resolution::Fuzzy);
        }
        if let Some(name) = pick(&format!("{wanted} {wanted} {context}")) {
            return (name, Resolution::Keywords);
        }
        return (FALLBACK, Resolution::Fallback);
    }
    match pick(context) {
        Some(name) => (name, Resolution::Keywords),
        None => (FALLBACK, Resolution::Fallback),
    }
}

const STOPWORDS: &[&str] = &[
    "app", "apps", "and", "the", "for", "with", "your", "you", "my", "mine", "see", "show", "shows", "keep", "keeps",
    "log", "logs", "track", "tracks", "tracker", "list", "lists", "day", "days", "daily", "each", "per", "how", "many",
    "much", "what", "when", "where", "which", "this", "that", "its", "are", "from", "into", "over", "them", "they",
    "let", "lets", "can", "will", "all", "any", "one", "new", "add", "get", "set", "sets", "use", "using", "custom",
    "during", "count", "counter", "item", "items", "entry", "entries", "time", "times", "today", "week", "month",
];

/// Words of free text, lowercased and stemmed, without stopwords.
fn keywords(text: &str) -> Vec<String> {
    text.split(|c: char| !c.is_ascii_alphanumeric())
        .map(|w| w.to_ascii_lowercase())
        .filter(|w| w.len() >= 3 && !STOPWORDS.contains(&w.as_str()))
        .map(|w| stem(&w))
        .collect()
}

/// A light plural stemmer: berries → berry, glasses → glass, boxes → box, expenses → expense.
fn stem(word: &str) -> String {
    let w = word.to_ascii_lowercase();
    if w.len() > 5 && w.ends_with("ies") {
        format!("{}y", &w[..w.len() - 3])
    } else if w.len() > 4
        && w.ends_with("es")
        && ["ss", "x", "z", "ch", "sh"].iter().any(|e| w[..w.len() - 2].ends_with(e))
    {
        w[..w.len() - 2].to_string()
    } else if w.len() > 3 && w.ends_with('s') && !["ss", "us", "is"].iter().any(|e| w.ends_with(e)) {
        w[..w.len() - 1].to_string()
    } else {
        w
    }
}

/// The best keyword match: name parts weigh most, then tag words, then prefixes. Earlier words count a little more.
fn pick(context: &str) -> Option<&'static str> {
    let words = keywords(context);
    if words.is_empty() {
        return None;
    }
    if let Some(name) = words.iter().find_map(|w| CONCEPTS.iter().find(|(k, _)| k == w).map(|(_, v)| *v)) {
        return Some(name);
    }
    let mut best: Option<(u32, &Entry)> = None;
    for e in CATALOG.iter() {
        let mut score = 0u32;
        for (i, w) in words.iter().enumerate() {
            let weight = if i < 3 { 2 } else { 1 };
            if e.parts.len() == 1 && e.parts[0] == w {
                score += 7 * weight;
            } else if e.parts.iter().any(|p| stem(p) == *w) {
                score += 4 * weight;
            } else if e.words.iter().any(|t| t == w) {
                score += 3 * weight;
            } else if w.len() >= 4
                && e.words.iter().any(|t| t.len() >= 4 && (t.starts_with(w.as_str()) || w.starts_with(t.as_str())))
            {
                score += weight;
            }
        }
        let better = match best {
            None => score > 0,
            Some((s, b)) => score > s || (score == s && (e.name.len(), e.name) < (b.name.len(), b.name)),
        };
        if better {
            best = Some((score, e));
        }
    }
    best.map(|(_, e)| e.name)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_and_aliases_are_consistent() {
        assert!(CATALOG.len() > 1500 && is_icon("barbell") && !is_icon("dumbbell") && is_icon(FALLBACK));
        for (from, to) in ALIASES {
            assert!(is_icon(to), "alias target `{to}` is not a Phosphor icon");
            assert!(!is_icon(from), "alias `{from}` shadows a real Phosphor icon");
        }
        for (word, to) in CONCEPTS {
            assert!(is_icon(to), "concept target `{to}` is not a Phosphor icon");
            assert_eq!(stem(word), *word, "concept key `{word}` must be stemmed");
        }
        assert_eq!(
            (stem("glasses"), stem("berries"), stem("boxes"), stem("pushups"), stem("expenses")),
            ("glass".into(), "berry".into(), "box".into(), "pushup".into(), "expense".into())
        );
    }

    #[test]
    fn resolves_names() {
        assert_eq!(resolve(Some("wallet"), ""), ("wallet", Resolution::Exact));
        assert_eq!(resolve(Some("dumbbell"), ""), ("barbell", Resolution::Alias));
        assert_eq!(resolve(Some("Trash 2"), ""), ("trash", Resolution::Alias));
        assert_eq!(resolve(Some("calendr"), ""), ("calendar", Resolution::Fuzzy));
        assert_eq!(resolve(Some("hydration"), "Water Tracker glasses of water").0, "drop");
    }

    #[test]
    fn picks_from_the_app_when_no_icon_is_given() {
        let pick = |ctx: &str| resolve(None, ctx).0;
        assert_eq!(pick("Pushup Tracker Log pushup sets and see when during the day you do them. tracker"), "barbell");
        assert_eq!(pick("Coffee counter cups of coffee"), "coffee");
        assert_eq!(pick("Expenses Log expenses by category"), "wallet");
        assert_eq!(pick("Sleep log bed time"), "bed");
        // No concept word: the tags decide.
        assert_eq!(pick("Bicycle rides"), "bicycle");
        assert_eq!(resolve(None, "the app"), (FALLBACK, Resolution::Fallback));
    }
}
